<svelte:head><title>The word · Fajr LMS</title></svelte:head>

{#snippet inTile(d: string, px: number, id: string)}
	<svg width={px} height={px} viewBox="0 0 48 48" fill="none" aria-hidden="true">
		<defs>
			<linearGradient id="sky-{id}" x1="0" y1="0" x2="1" y2="1">
				<stop offset="0" stop-color={SKY} />
				<stop offset="1" stop-color={HORIZON} />
			</linearGradient>
			<radialGradient id="sun-{id}" cx="0.5" cy="0.5" r="0.5">
				<stop offset="0" stop-color={SUN} stop-opacity="1" />
				<stop offset="0.4" stop-color={SUN} stop-opacity="0.94" />
				<stop offset="0.7" stop-color={SUN} stop-opacity="0.34" />
				<stop offset="1" stop-color={SUN} stop-opacity="0" />
			</radialGradient>
			<clipPath id="tile-{id}"><path d={TILE} /></clipPath>
		</defs>
		<path d={TILE} fill="url(#sky-{id})" />
		<g clip-path="url(#tile-{id})">
			<circle cx="37" cy="42" r="24" fill="url(#sun-{id})" />
		</g>
		<path {d} fill={INK} fill-opacity="0.96" />
	</svg>
{/snippet}

<div class="wrap">
	<header>
		<p class="eyebrow">Fajr LMS · the word</p>
		<h1>فجر, in eight hands</h1>
		<p class="lede">
			The whole word, shaped and joined the way it is written rather than three letters set beside
			one another. Each is shown as a wordmark on its own, and squeezed into the tile — a word in a
			28-pixel icon is a different question from a word on a page.
		</p>
	</header>

	<div class="stack">
		{#each HANDS as hand, index (hand.label)}
			<article class="card">
				<div class="head">
					<h2>{hand.label}</h2>
					<span class="note">{hand.note}</span>
				</div>

				<div class="word">
					<svg viewBox="0 0 48 48" width="260" height="260" fill="none" aria-hidden="true">
						<path d={hand.d} fill={INK} />
					</svg>
				</div>

				<div class="tiles">
					{@render inTile(hand.d, 96, `a-${index}`)}
					{@render inTile(hand.d, 44, `b-${index}`)}
					{@render inTile(hand.d, 28, `c-${index}`)}
					{@render inTile(hand.d, 16, `d-${index}`)}
				</div>
			</article>
		{/each}
	</div>
</div>

